```

Example 3: MAJOR input

```stan
data {
  int<lower=1> N;
  vector[N] y;
}
parameters {
  real mu1;
  real mu2;
}
model {
  for (n in 1:N) {
    target += log_mix(0.5, normal_lpdf(y[n] | mu1, 1), normal_lpdf(y[n] | mu2, 1));
  }
