// Equiv: bioequivalence in a cross-over trial
//  http://www.openbugs.net/Examples/Equiv.html

data {
  int<lower=0> P;
  int<lower=0> N;
  array[N] int group;
  array[N, P] real Y;
  array[2] int sign;
}
transformed data {
  array[N, P] int T;
  for (n in 1 : N) {
    for (p in 1 : P) {
      T[n, p] = (group[n] * (2 * p - 3) + 3) %/% 2;
    }
  }
}
parameters {
  real mu;
  real phi;
  real pi;
  real<lower=0> sigmasq1;
  real<lower=0> sigmasq2;
  array[N] real delta;
}
transformed parameters {
  real sigma1;
  real sigma2;
  sigma1 = sqrt(sigmasq1);
  sigma2 = sqrt(sigmasq2);
}
model {
  for (n in 1 : N) {
    vector[P] m;
    for (p in 1 : P) {
      m[p] = mu + sign[T[n, p]] * phi / 2 + sign[p] * pi / 2 + delta[n];
    }
    Y[n] ~ normal(m, sigma1);
  }
  delta ~ normal(0, sigma2);
  sigmasq1 ~ inv_gamma(.001, .001);
  sigmasq2 ~ inv_gamma(.001, .001);
  mu ~ normal(0.0, 1000);
  phi ~ normal(0.0, 1000);
  pi ~ normal(0.0, 1000);
}
generated quantities {
  real equiv;
