data {
  int<lower=0> N;
  array[N] int<lower=0> x;
  array[N] int<lower=0> y;
  array[N] int<lower=0> t;
}
parameters {
  real alpha;
  real delta;
}
transformed parameters {
  real<lower=0, upper=1> theta;
  theta = inv_logit(delta);
}
model {
  real p;
  real log1m_theta;
  p = inv_logit(alpha);
  log1m_theta = log1m(theta);

  alpha ~ normal(0, 100);
  delta ~ normal(0, 100);
